import * as T from './vendor/three.module.js';
import {createFoundryKit} from './foundry-kit.mjs';
import {AFTERLIGHT_THINGS,AFTERLIGHT_COVER,afterlightStage,afterlightGoal} from './afterlight-world.mjs';
import {groundAt,occupied,clearLine} from './model.mjs';
/* A small reusable visual kit. It reads progress; it cannot award an objective. */
export function installAfterlightScene(scene){
 const kit=createFoundryKit(scene),{root,add,sign,batch}=kit;root.name='bellwether-afterlight';const dials=[],bulbs=[];let markerCount=0;
 for(const t of AFTERLIGHT_THINGS){const g=new T.Group();g.name=t.id;g.position.set(t.x,t.y,t.z);root.add(g);
  add('box','metal',[0,.55,0],[.8,1.1,.48],g);
  if(t.dial!==undefined){const wheel=add('ring','brass',[0,1.33,.1],[.42,.42,.42],g);add('box','paper',[0,.24,0],[.07,.25,.07],wheel);dials.push({mesh:wheel,index:t.dial});for(let i=0;i<4;i++){const a=i*Math.PI/2;add('sphere','paper',[Math.sin(a)*.54,1.33+Math.cos(a)*.54,.1],[.05,.05,.05],g);}}
  else if(t.id==='afterlight-beacon'){add('cylinder','brass',[0,1.6,0],[.07,2.3,.07],g);const lens=add('sphere','glow',[0,2.5,0],[.26,.26,.26],g);bulbs.push(lens);}
  else if(t.id==='afterlight-fuse'){add('cylinder','brass',[0,.95,0],[.18,.6,.18],g);g.userData.fuse=true;}
  else add('box','paper',[0,1.3,.02],[1.05,.45,.1],g);
  sign(t.id==='afterlight-board'?'BELLWETHER AFTERLIGHT / DISPATCH':t.id==='afterlight-clue'?'ELECTRICIAN: A=3 / B=1 / C=2':t.id==='afterlight-test'?'ARCADE / TEST CIRCUIT':t.dial!==undefined?'RELAY '+['A','B','C'][t.dial]:'AFTERLIGHT / '+(t.id==='afterlight-fuse'?'FUSE':'BROADCAST'),t.x,t.y+(t.dial!==undefined?2.4:3.4),t.z+.15,t.dial!==undefined?2.4:4.2);
 }
 for(const c of AFTERLIGHT_COVER)batch('box','metal',[(c.x1+c.x2)/2,(c.y1+c.y2)/2,(c.z1+c.z2)/2],[c.x2-c.x1,c.y2-c.y1,c.z2-c.z1]);
 // Restore these public lanterns at the end, not the lighting of unrelated districts.
 for(const [x,z]of[[-87,-3],[-97,-19],[-111,-19],[-88,-35],[-98,-35],[-113,-15]]){batch('cylinder','dark',[x,8.6,z],[.055,3.2,.055]);batch('box','brass',[x,10.35,z],[.5,.7,.5]);bulbs.push(add('sphere','glow',[x,10.35,z],[.22,.28,.22]));}
 const goalRing=add('ring','brass',[0,0,0],[.65,.65,.65]);goalRing.rotation.x=Math.PI/2;
 const arrows=Array.from({length:8},()=>{const g=new T.Group();root.add(g);for(const side of[-1,1]){const wing=add('box','glow',[side*.16,0,.18],[.075,.035,.55],g);wing.rotation.y=side*Math.PI/4;}g.visible=false;return g;});kit.flush();
 function update(s,{menu=false,reduced=false}={}){const stage=afterlightStage(s);for(const d of dials)d.mesh.rotation.z=-s.expedition.afterlightDials[d.index]*Math.PI/2;for(const b of bulbs)b.visible=stage>=5;
  const fuse=root.getObjectByName('afterlight-fuse');if(fuse)fuse.visible=stage<2;
  const tracked=!menu&&s.expedition.tracked==='afterlight'&&stage<5,goal=afterlightGoal(s);goalRing.visible=tracked;goalRing.position.set(goal.x,goal.y+.05,goal.z);if(!reduced)goalRing.rotation.z=s.time*.4;
  markerCount=0;const dx=goal.x-s.p.x,dz=goal.z-s.p.z,len=Math.hypot(dx,dz),yaw=Math.atan2(dx,-dz);let open=tracked&&s.skirmish?.navigateUntil>s.time&&s.p.grounded&&Math.abs(s.p.y-goal.y)<1.5;
  arrows.forEach((g,i)=>{const d=(i+1)*1.25,x=s.p.x+dx/(len||1)*d,z=s.p.z+dz/(len||1)*d,y=groundAt(x,z,s.p.y+.5).y;
   if(!Number.isFinite(y)||Math.abs(y-s.p.y)>.45||occupied(x,y,z,s)||!clearLine({...s.p,y:s.p.y+.55},{x,y:y+.55,z},s)||d>len)open=false;
   g.visible=!!open;if(open){g.position.set(x,y+.035,z);g.rotation.y=yaw;markerCount++;}
  });
 }
 return{update,dispose:kit.dispose,stats:()=>({lanterns:bulbs.length,routeMarkers:markerCount,waypoints:AFTERLIGHT_THINGS.length})};
}

/* Original public district episode. Shared IDs drive simulation, journal and art. */
export const AFTERLIGHT_TASK = Object.freeze({id:'afterlight',name:'Bellwether Afterlight',reward:240,flag:'afterlight-complete',description:'Recover a guarded fuse, repair the Clockmaker\'s Arcade switchboard, climb the Theatre roof, protect its broadcast and return to relight Bellwether. One connected district adventure; progress survives checkpoints.'});
export const AFTERLIGHT_FLAGS=Object.freeze(['afterlight-started','afterlight-fuse','afterlight-circuit','afterlight-beacon','afterlight-complete']);
export const AFTERLIGHT_CODE=Object.freeze([3,1,2]);
export const AFTERLIGHT_THINGS=Object.freeze([
 {id:'afterlight-board',name:'Afterlight dispatch / begin or finish',x:-84,y:7,z:-4,kind:'afterlight'},
 {id:'afterlight-fuse',name:'Sealed lighting fuse / clear guards then collect',x:-75,y:7,z:-20,kind:'afterlight'},
 ...[-107,-103,-99].map((x,i)=>({id:'afterlight-dial-'+i,name:'Arcade relay '+['A','B','C'][i]+' / turn',x,y:7,z:-33,kind:'afterlight',dial:i})),
 {id:'afterlight-clue',name:'Read the electrician\'s plate',x:-107,y:7,z:-26,kind:'afterlight'},
 {id:'afterlight-test',name:'Arcade switchboard / test circuit',x:-98,y:7,z:-26,kind:'afterlight'},
 {id:'afterlight-beacon',name:'Theatre broadcast / hold the roof',x:-110,y:27.5,z:-5,kind:'afterlight'}
]);
export const AFTERLIGHT_COVER=Object.freeze([
 {id:'afterlight-roof-crate',x1:-113.1,x2:-110.7,y1:27.5,y2:28.65,z1:-8.6,z2:-7.4}
]);
export const AFTERLIGHT_HINTS=Object.freeze([
 'Reach Bellwether by the west stairs or Bellwether Local rail. Read the Afterlight dispatch near the eastern arrival.',
 'Walk south to the sealed fuse. Use it to challenge two guards, defeat them, then use it again to recover the fuse.',
 'Enter the Clockmaker\'s Arcade through its south doorway. Read the plate, turn relays A/B/C to 3/1/2, then test the circuit.',
 'Use the Theatre service ladder north of the Arcade. On the roof, start the broadcast, defeat both guards and hold for 20 seconds.',
 'Descend the service ladder or Foldwing to the street. Return to the Afterlight dispatch to relight the market and collect your reward.',
 'Bellwether is relit. Your 240-credit reward is saved; the other adventures remain available.'
]);
export const afterlightStage=s=>{const flags=s.expedition?.flags||[];let n=0;while(n<AFTERLIGHT_FLAGS.length&&flags.includes(AFTERLIGHT_FLAGS[n]))n++;return n;};
export function cleanAfterlightFlags(flags){const have=new Set(flags),out=flags.filter(f=>!AFTERLIGHT_FLAGS.includes(f));for(const f of AFTERLIGHT_FLAGS){if(!have.has(f))break;out.push(f);}return out;}
export function afterlightGoal(s){const stage=afterlightStage(s),find=id=>AFTERLIGHT_THINGS.find(t=>t.id===id),p=s.p;
 if(stage===0||stage===5)return find('afterlight-board');
 if(stage===1)return find('afterlight-fuse');
 if(stage===2){if(p.z>-21.8&&Math.hypot(p.x+103,p.z+21.5)>1.5)return{x:-103,y:7,z:-21.5,name:'Clockmaker\'s Arcade south doorway'};const i=s.expedition.afterlightDials.findIndex((v,i)=>v!==AFTERLIGHT_CODE[i]);return find(i<0?'afterlight-test':'afterlight-dial-'+i);}
 if(stage===3&&p.y<24)return{x:-107,y:7,z:.1,name:'Theatre service ladder / X climbs'};
 if(stage===4&&p.y>24)return{x:-107,y:27.5,z:-2.1,name:'Theatre ladder / X then stick down'};
 return find(stage===3?'afterlight-beacon':'afterlight-board');
}
